SELECT e.ref_id, s.id, s.symbol, s.decision, s.generated_at, s.latest_price FROM (SELECT 156723 AS ref_id, 'EGLDUSDT' AS sym, '2026-10-11 20:55:01.575650' AS g UNION ALL SELECT 159408,'EGLDUSDT','2026-10-11 22:40:01.633945' UNION ALL SELECT 165412,'XRPUSDT','2026-10-12 02:35:01.469482' UNION ALL SELECT 167668,'DOGEUSDT','2026-10-12 04:02:02.813094' UNION ALL SELECT 171589,'SHIBUSDT','2026-10-12 06:36:01.506950' UNION ALL SELECT 176710,'ACEUSDT','2026-10-12 09:57:01.850059') e JOIN crypto_ai.trade_signal s ON s.symbol=e.sym AND s.interval_code='1m' AND s.signal_mode='LIVE' AND s.generated_at BETWEEN DATE_SUB(e.g, INTERVAL 30 MINUTE) AND e.g ORDER BY e.ref_id, s.generated_at LIMIT 220;
SELECT id, symbol, status, started_at, anchor_entry_price, best_entry_price, latest_signal_id, executed_at FROM crypto_ai.execution_opportunity WHERE (symbol='EGLDUSDT' AND started_at BETWEEN '2026-10-11 18:50:00' AND '2026-10-11 22:41:00') OR (symbol='XRPUSDT' AND started_at BETWEEN '2026-10-12 00:30:00' AND '2026-10-12 02:36:00') OR (symbol='DOGEUSDT' AND started_at BETWEEN '2026-10-12 02:00:00' AND '2026-10-12 04:03:00') OR (symbol='SHIBUSDT' AND started_at BETWEEN '2026-10-12 04:30:00' AND '2026-10-12 06:37:00') OR (symbol='ACEUSDT' AND started_at BETWEEN '2026-10-12 08:00:00' AND '2026-10-12 09:58:00') ORDER BY symbol, started_at LIMIT 40;